-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "zhTW" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.deathknight.blood.Name"] = "推薦"
L["rm.mop.deathknight.blood.Description"] = "推薦血魄坦克使用，在血魄專精下選用。從遠處以疫病爆發、冰結之觸或死亡之握拉怪。生命力低於一半、沒有血魄護盾時（80 級起），以及四個冰霜與穢邪符文全部充滿之前使用死亡打擊；符能接近 90 時使用符文打擊（學會前於 80 時用死亡纏繞）；以疫病爆發（否則冰結之觸與瘟疫打擊）施加疾病，68 級起以沸血術刷新疾病；低於 35% 時使用靈魂收割者；兩個血魄符文時使用碎心打擊（60 級前為血魄打擊）；疾病持續期間赤血災禍觸發時使用死亡凋零，否則使用沸血術；十一層充能時使用血魄轉化；然後是死亡打擊、碎心打擊、符文打擊與凜冬號角。三個敵人與你交戰時：死亡凋零、擴散疾病（有鮮血同化時用沸血術，否則用瘟疫同化）與沸血術。提醒：沒有領域時使用血魄領域、骸骨之盾、凜冬號角、心智冰封、依你的生命力使用符文轉化、血族之裔、冰錮堅韌、強力符文武器與死亡契約，對精英使用符文武器幻舞，隊伍首領戰前使用亡靈大軍。它無法看到即將承受的傷害，因此反魔法護罩（預設關閉）與大型防禦技能由你負責。"
L["rm.mop.deathknight.blood.simulator.Name"] = "依生命力反應（模擬器）"
L["rm.mop.deathknight.blood.simulator.Description"] = "推薦血魄內建循環的替代方案，適合有治療者的團隊坦克，預設關閉：啟用它並停用推薦的循環，或提高它的優先順序。死亡打擊只在生命力低於 70%、血魄護盾缺少或即將消失，或冰霜與穢邪符文即將溢出前使用，而不是每有符文就使用；當冰霜與穢邪符文還要超過一秒才就緒時，單獨的血魄符文用於碎心打擊。它沒有範圍效果段落，提醒與推薦的循環相同。"
L["rm.mop.deathknight.frost.Name"] = "雙手武器"
L["rm.mop.deathknight.frost.Description"] = "雙手武器的冰霜，常見的升級配置；在冰霜專精下，雙持內建循環不適用時選用。開場、疾病、生存與範圍傷害與雙持內建循環相同，接著殺戮酷刑觸發時使用滅寂，符能高於 76 時使用冰霜打擊，凝霜觸發時使用凜風衝擊，有一對符文充滿時使用滅寂，滅寂，凜風衝擊，瘟疫汲取，40 時使用冰霜打擊，以及凜冬號角。學會滅寂（58 級）之前，以死亡打擊消耗你的穢邪符文。提醒與雙持內建循環相同。"
L["rm.mop.deathknight.frost.dualwield.Name"] = "雙持"
L["rm.mop.deathknight.frost.dualwield.Description"] = "推薦以兩把單手武器的冰霜使用（Masterfrost）；在冰霜專精下，且你的副手持有武器時選用。以疫病爆發或凜風衝擊拉怪（單人時用死亡之握）。黑暗救贖觸發或生命力低於 35% 時使用死亡打擊，十一層充能時使用血魄轉化，疾病（穢邪荒疫、疫病爆發、凜風衝擊、瘟疫打擊），低於 35% 時使用靈魂收割者，殺戮酷刑觸發或符能高於 89 時使用冰霜打擊，凝霜觸發或兩個冰霜符文或兩個死亡符文都就緒時使用凜風衝擊，符能低於 77 且有兩個穢邪符文時使用滅寂，高於 76 時使用冰霜打擊，滅寂，凜風衝擊，疾病即將消失且疫病爆發就緒時使用瘟疫汲取，40 時使用冰霜打擊，凜冬號角。三個敵人與你交戰時：擴散疾病、死亡凋零與凜風衝擊。提醒：冰霜領域、冰霜之柱、死者復生、所有符文都用完時使用強力符文武器、凜冬號角、心智冰封、生命力低時使用冰錮堅韌與死亡契約、隊伍首領戰前使用亡靈大軍。"
L["rm.mop.deathknight.unholy.Name"] = "穢邪"
L["rm.mop.deathknight.unholy.Description"] = "推薦穢邪使用，也是血魄與冰霜都不適用的死亡騎士（包括沒有專精者）的內建循環。從遠處以疫病爆發或冰結之觸拉怪（單人時用死亡之握）。黑暗救贖觸發或生命力低於 35% 時使用死亡打擊，疾病（穢邪荒疫、疫病爆發、瘟疫打擊、冰結之觸），十一層充能時使用血魄轉化，低於 35% 時使用靈魂收割者，五層闇能灌注時使用黑暗變形，符能接近上限時使用死亡纏繞，對會存活的目標使用死亡凋零，天譴打擊，厄運驟臨觸發或 40 時使用死亡纏繞，穢邪力量生效時使用疫病爆發，膿瘡潰擊（學會前用血魄打擊），瘟疫汲取，凜冬號角。三個敵人與你交戰時：擴散疾病、死亡凋零、沸血術，以及有冰霜符文時使用冰結之觸。提醒：穢邪領域、你的食屍鬼、嗜血術期間或長時間精英戰鬥時使用召喚石像鬼、邪惡狂熱、強力符文武器、凜冬號角、心智冰封、生命力低時使用冰錮堅韌與死亡契約、隊伍首領戰前使用亡靈大軍；反魔法護罩預設關閉。"
L["rm.mop.deathknight.unholy.simulator.Name"] = "穢邪，符文溢出前蓄積（模擬器）"
L["rm.mop.deathknight.unholy.simulator.Description"] = "推薦穢邪內建循環的替代方案，依照模擬器、wowtbc.gg、Method 與 MaxDps 的打法；預設關閉：啟用它並停用推薦的循環，或提高它的優先順序。黑暗變形未生效時，死亡纏繞用於重新累積闇能灌注，兩個穢邪符文或兩個死亡符文都就緒時優先使用天譴打擊，兩個血魄與兩個冰霜符文都就緒時優先使用膿瘡潰擊；其餘開場、疾病、範圍傷害與提醒與推薦的循環相同。"
L["rm.retail.deathknight.blood.Name"] = "暴雪戰鬥助手"
L["rm.retail.deathknight.blood.Description"] = "推薦血魄專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：戰鬥中的血族之裔與死者復生、對可中斷的施法使用心智冰封，以及戰鬥中只要就緒就使用冰錮堅韌與你的種族冷卻技能。敵人的施法在戰鬥中會被隱藏，因此心智冰封只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此何時使用冰錮堅韌由你決定。主動減傷的時機、反魔法護罩、嘲諷與飾品由你自行處理。"
L["rm.retail.deathknight.blood.guide.Name"] = "參考（Icy Veins 與 Wowhead）"
L["rm.retail.deathknight.blood.guide.Description"] = "僅供參考，預設關閉：指南中的血魄優先順序。在至暗之夜的戰鬥中，你的增益效果與目標的減益效果都對插件隱藏，因此讀取它們的步驟會在那裡等待；可以閱讀它，或複製後自行實驗。正式版中生命力與符能是隱藏的，因此只要負擔得起就使用死亡打擊。以死亡的撫慰拉怪。死亡打擊；骸骨之盾消失、少於五層、即將結束或消滅生效時使用撕骨裂髓（不在近戰範圍時改用死亡的撫慰）；煞婪贈禮期間，死亡打擊，使用一次沸血術，赤血災禍觸發時使用死亡凋零，以及碎心打擊；赤血災禍觸發或面對四個敵人時使用死亡凋零；吸血打擊；吞噬；沸點觸發、血魄瘟疫消失或充能已滿時使用沸血術；碎心打擊。提醒：死者復生、血族之裔、奪魂印記、在奪魂印記之後使用符文武器幻舞，以及戰鬥助手內建循環中的功能性提醒。"
L["rm.retail.deathknight.blood.simc.Name"] = "死亡召喚者參考（SimulationCraft）"
L["rm.retail.deathknight.blood.simc.Description"] = "僅供參考，預設關閉：SimulationCraft 的死亡召喚者清單，會把符能花在死亡打擊上來造成傷害。由於戰鬥資料被隱藏，它無法在至暗之夜的戰鬥中運作，而且正式版中符能是隱藏的，因此沒有溢出傾瀉。死亡凋零未生效時隨時使用，奪魂印記，消滅生效時使用撕骨裂髓，符文不足時以死亡的撫慰維持骸骨之盾（否則使用撕骨裂髓），死亡打擊，沸血術，符文武器幻舞以外的時間使用吞噬，碎心打擊。提醒：死者復生、符文武器幻舞、血族之裔以及功能性提醒。"
L["rm.retail.deathknight.frost.Name"] = "暴雪戰鬥助手"
L["rm.retail.deathknight.frost.Description"] = "推薦冰霜專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時提醒戰鬥助手留給你處理的部分：戰鬥中的辛德拉苟莎之息與死者復生、對可中斷的施法使用心智冰封，以及戰鬥中只要就緒就使用冰錮堅韌與你的種族冷卻技能。敵人的施法在戰鬥中會被隱藏，因此心智冰封只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此何時使用冰錮堅韌由你決定。"
L["rm.retail.deathknight.frost.guide.Name"] = "參考（Icy Veins 與 SimulationCraft）"
L["rm.retail.deathknight.frost.guide.Description"] = "僅供參考，預設關閉：指南中的冰霜優先順序。殺戮酷刑、凝霜與冰剃在至暗之夜的戰鬥中會被隱藏，因此它無法在戰鬥中運作；正式版中符能是隱藏的，因此沒有溢出檢查。擁有兩層殺戮酷刑，或一層殺戮酷刑且有三個符文時使用滅寂，有粉碎之刃時在冰剃疊滿五層時使用冰霜打擊，凝霜觸發時使用凜風衝擊，殺戮酷刑觸發時使用滅寂，冰霜打擊，滅寂；三個以上敵人時改用冰霜鐮刀與冰川突進；不在近戰範圍時使用凜風衝擊。提醒：冷酷凜冬、冰霜之柱、在冰霜之柱期間使用辛德拉苟莎之息與冰霜巨龍之怒、奪魂印記、死者復生、在兩層充能時使用強力符文武器，以及功能性提醒。"
L["rm.retail.deathknight.frost.wowhead.Name"] = "參考（Wowhead）"
L["rm.retail.deathknight.frost.wowhead.Description"] = "僅供參考，預設關閉：Wowhead 的冰霜施放順序，把冷卻技能也排進了循環。由於戰鬥資料被隱藏，它無法在至暗之夜的戰鬥中運作；正式版中符能是隱藏的，因此沒有溢出檢查。兩層充能時使用強力符文武器，奪魂印記，冰霜之柱，辛德拉苟莎之息，冰霜巨龍之怒；接著擁有兩層殺戮酷刑，或一層殺戮酷刑且消滅生效時使用滅寂，凝霜觸發時使用凜風衝擊，殺戮酷刑觸發時使用滅寂，使用強力符文武器獲得新的殺戮酷刑，冰霜打擊，滅寂，凜風衝擊。三個以上敵人時改用冰霜鐮刀與冰川突進。"
L["rm.retail.deathknight.initial.Name"] = "暴雪戰鬥助手"
L["rm.retail.deathknight.initial.Description"] = "在你選擇專精之前推薦使用（此時遊戲回報的是死亡騎士的初始專精）。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議；你施法或引導時它會等待。同時附上每個死亡騎士內建循環共用的提醒，各項在你學會對應法術後才會出現。當你在 10 級選擇專精後，該專精的內建循環會接手。"
L["rm.retail.deathknight.unholy.Name"] = "暴雪戰鬥助手"
L["rm.retail.deathknight.unholy.Description"] = "推薦穢邪專精使用。醒目提示暴雪戰鬥助手建議的下一個法術，這是在至暗之夜的戰鬥中，遊戲仍允許插件讀取的唯一循環建議（它會自行召喚食屍鬼，並自行使用亡靈大軍與黑暗變身）；你施法或引導時它會等待。同時提醒：對可中斷的施法使用心智冰封，以及戰鬥中只要就緒就使用冰錮堅韌與你的種族冷卻技能。敵人的施法在戰鬥中會被隱藏，因此心智冰封只會在遊戲顯示它們的場合亮起；正式版中生命力是隱藏的，因此何時使用冰錮堅韌由你決定。"
L["rm.retail.deathknight.unholy.guide.Name"] = "參考（Icy Veins 與 Wowhead）"
L["rm.retail.deathknight.unholy.guide.Description"] = "僅供參考，預設關閉：指南中的穢邪優先順序。觸發效果與疫病在至暗之夜的戰鬥中會被隱藏，因此它無法在戰鬥中運作；正式版中符能與目標的生命力是隱藏的，因此斬殺階段與煞婪的符能消耗都未納入。沒有食屍鬼時使用死者復生；使用膿瘡鐮刀維持其疫病帶來的加速；奪魂觸發時使用靈魂收割者；黑暗變身期間使用敗壞；厄運驟臨或禁忌知識觸發時使用死亡纏繞（四個以上敵人時改用疫情蔓延）；沒有低階食屍鬼充能時使用膿瘡潰擊，有充能時使用天譴打擊；死亡纏繞。提醒：亡靈大軍、黑暗變身、疫病消失時使用疫病爆發，以及功能性提醒。"
L["rm.retail.deathknight.unholy.simc.Name"] = "參考（SimulationCraft）"
L["rm.retail.deathknight.unholy.simc.Description"] = "僅供參考，預設關閉：SimulationCraft 的穢邪清單，使用死亡纏繞的頻率要高得多。由於戰鬥資料被隱藏，它無法在至暗之夜的戰鬥中運作；正式版中符能與目標生命力是隱藏的，因此溢出與斬殺階段的判斷都未納入。維持膿瘡鐮刀，黑暗變身期間使用靈魂收割者，厄運驟臨觸發時使用死亡纏繞，黑暗變身期間使用敗壞，黑暗變身或禁忌知識期間，以及亡靈大軍還有 5 秒以上才就緒時使用死亡纏繞，有低階食屍鬼充能時使用天譴打擊，膿瘡潰擊。三個以上敵人時：以疫情蔓延取代死亡纏繞，低階食屍鬼充能少於三層時使用膿瘡潰擊。提醒：疫病爆發、對成群敵人使用死亡凋零、亡靈大軍、黑暗變身。"
